'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/escrow — hold funds from a buyer until release conditions are met
 * (e.g. delivery confirmation), then pay out to a courier/seller.
 */
class Escrow {
  constructor(client) {
    this.client = client;
  }

  /**
   * List escrow transactions.
   * @param {object} [params]
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/escrow', params));
  }

  /**
   * Create an escrow transaction.
   * @param {object} params
   * @param {object} params.buyer     { first_name, last_name, phone, operator, otp }
   * @param {object} params.courier   { first_name, last_name, phone, operator }
   * @param {number} params.amount
   * @param {string} params.currency
   * @param {string} [params.description]
   * @param {string} [params.external_ref]
   * @param {object} [params.metadata]
   */
  create(params) {
    return this.client.request('POST', '/v1/escrow', params);
  }

  /**
   * Retrieve an escrow transaction by ID.
   * @param {string} id
   */
  retrieve(id) {
    return this.client.request('GET', `/v1/escrow/${encodeURIComponent(id)}`);
  }

  /**
   * Release held funds to the courier/seller.
   * @param {string} id
   * @param {object} params
   * @param {string} params.release_code
   */
  release(id, params) {
    return this.client.request('POST', `/v1/escrow/${encodeURIComponent(id)}/release`, params);
  }

  /**
   * Open a dispute on an escrow transaction.
   * @param {string} id
   * @param {object} params
   * @param {string} params.reason
   */
  dispute(id, params) {
    return this.client.request('POST', `/v1/escrow/${encodeURIComponent(id)}/dispute`, params);
  }

  /**
   * Cancel an escrow transaction (refund the buyer).
   * @param {string} id
   * @param {object} params
   * @param {string} params.reason
   */
  cancel(id, params) {
    return this.client.request('POST', `/v1/escrow/${encodeURIComponent(id)}/cancel`, params);
  }
}

module.exports = Escrow;
